<script setup>
const localRuntime=globalThis.HARDWARE_MONITOR_LOCAL===true;
import {t,preference,setLanguage} from './i18n.js';
import { computed,onMounted,onUnmounted,reactive,ref,toRefs } from 'vue';
import { overall,measurementSnapshot,labels,timestamp,primaryAlarms,summaryAlarms,assessmentReason,observationStatus,observationLabel,retainedObservationStatus } from './health.js';
import { updateSession } from './session.js';
import { administer } from './device-api.js';
import DeviceEditor from './DeviceEditor.vue';
import AlarmRow from './AlarmRow.vue';
import MailSettings from './MailSettings.vue';
import MailReplay from './MailReplay.vue';
import NotificationSettings from './NotificationSettings.vue';
import HistoryActions from './HistoryActions.vue';
import BackupSettings from './BackupSettings.vue';
import HistorySettings from './HistorySettings.vue';
import {eventType,deliveryText,filterEvents,sourceTimestamp,capabilityText,groupEvents} from './events.js';
const uiBuild=__UI_BUILD__;
const session=reactive({dashboard:null,error:'',authRequired:false});
const {dashboard,error,authRequired}=toRefs(session);
const loading=ref(false),selected=ref(''),tab=ref('overview'),editor=ref(null);
const replayEvent=ref(null);
const admin=computed(()=>dashboard.value?.user?.role==='administrator');
function changeLanguage(event){setLanguage(event.target.value);refresh();}
async function saved(id){editor.value=null;if(id)selected.value=id;await refresh();}
let timer,controller,desktopController,refreshAgain=false;
const alarmFilter=ref('all');
const desktopTest=reactive({level:'info',busy:false,message:'',error:''});
async function sendDesktopTest(){
  if(desktopTest.busy)return;
  desktopTest.busy=true;desktopTest.error='';desktopTest.message='';desktopController=new AbortController();
  const timeout=setTimeout(()=>desktopController.abort(),15000);
  try{const response=await administer(dashboard.value,{action:'desktop_test',level:desktopTest.level},fetch,desktopController.signal);desktopTest.message=response.message;await refresh();}
  catch(error){desktopTest.error=error.name==='AbortError'?t("Zeitüberschreitung. Bitte vor einem erneuten Versuch die DSM-Benachrichtigungen prüfen."):error.message;}
  finally{clearTimeout(timeout);desktopTest.busy=false;}
}
onUnmounted(()=>desktopController?.abort());
const devices=computed(()=>dashboard.value?.devices??[]);
const eventFilter=reactive({category:'all',health:'all',device:'all'});
const groupedEvents=computed(()=>groupEvents(dashboard.value?.events??[]));
const visibleEvents=computed(()=>filterEvents(groupedEvents.value,eventFilter));
const eventDevices=computed(()=>[...new Map((dashboard.value?.events??[]).map(e=>[e.device,e.device_name??e.device])).entries()]);
const focus=computed(()=>devices.value.find(d=>d.device.id===selected.value));
const focusSnapshot=computed(()=>measurementSnapshot(focus.value));
const counts=computed(()=>devices.value.reduce((a,d)=>{a[overall(d)]++;return a;},{ok:0,warning:0,critical:0,acknowledged:0,unknown:0}));
async function refresh(){
  if(loading.value){refreshAgain=true;return;}
  loading.value=true;controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),12000);
  try {
    await updateSession(session,fetch,controller.signal);
    if(!devices.value.some(d=>d.device.id===selected.value))selected.value=devices.value[0]?.device.id??'';
    if(!dashboard.value)selected.value='';
  }finally{clearTimeout(timeout);loading.value=false;if(refreshAgain){refreshAgain=false;refresh();}}
}
function checkVisible(){if(document.visibilityState==='visible')refresh();}
onMounted(()=>document.addEventListener('visibilitychange',checkVisible));
onUnmounted(()=>document.removeEventListener('visibilitychange',checkVisible));
onMounted(()=>{refresh();timer=setInterval(refresh,30000)});
onUnmounted(()=>{clearInterval(timer);controller?.abort()});
</script>
<template>
<div v-if="!dashboard" class="session-gate" role="status" :aria-busy="loading">
  <div class="session-card"><div class="language-picker"><label>{{t('Sprache')}} <select :value="preference" @change="changeLanguage"><option value="auto">{{t('Automatisch')}}</option><option value="de">Deutsch</option><option value="en">English</option></select></label></div><span class="brand-mark">▥</span><h1>Hardware Monitor</h1><p class="ui-build">{{t("Oberfläche")}} {{uiBuild}}</p>
    <template v-if="loading"><h2>{{localRuntime?t("Lokale Anwendung wird geladen …"):t("DSM-Anmeldung wird geprüft …")}}</h2><p>{{localRuntime?t("Verbindung zum lokalen Entwicklungsdienst wird hergestellt."):t("Geräte und Ereignisse werden erst nach erfolgreicher Prüfung geladen.")}}</p></template>
    <template v-else><h2>{{authRequired?t("DSM-Anmeldung erforderlich"):t("Verbindung nicht verfügbar")}}</h2><p>{{error||t("Bitte in DSM anmelden und die Anwendung erneut öffnen.")}}</p><p>{{localRuntime?t("Bitte den lokalen Entwicklungsdienst starten und erneut versuchen."):t("Eine aktive DSM-Sitzung und eine berechtigte Benutzergruppe sind erforderlich.")}}</p><a v-if="!localRuntime" href="/" target="_top">{{t("Zur DSM-Anmeldung")}}</a><button class="refresh" @click="refresh">{{t("Erneut prüfen")}}</button></template>
  </div>
</div>
<div v-else class="shell">
  <aside><div class="brand"><span class="brand-mark">▥</span><div>Hardware<span>MONITOR</span></div></div><p class="eyebrow">{{t("INFRASTRUKTUR")}}</p><button :class="{active:tab==='overview'}" @click="tab='overview'">{{t("▦   Geräteübersicht")}}</button><button :class="{active:tab==='events'}" @click="tab='events'">{{t("◷   Ereignisse")}} <span class="count">{{groupedEvents.length}}</span></button><button v-if="admin" :class="{active:tab==='mail'}" @click="tab='mail'">{{t("✉   Benachrichtigungen")}}</button><button v-if="admin" :class="{active:tab==='backup'}" @click="tab='backup'">{{t("▣   Sicherung")}}</button><button v-if="admin" :class="{active:tab==='audit'}" @click="tab='audit'">{{t("≡   Änderungsprotokoll")}}</button><div class="aside-foot"><span class="dot"></span> {{dashboard.runtime==='local-development'?t("Lokale Entwicklung · ohne Login"):t("Lokal auf deiner Synology")}}<small>{{t("Hardwareüberwachung · Version")}} {{dashboard?.version??'0.1.0'}}</small></div></aside>
  <main><div class="language-picker"><label>{{t('Sprache')}} <select :value="preference" @change="changeLanguage"><option value="auto">{{t('Automatisch')}}</option><option value="de">Deutsch</option><option value="en">English</option></select></label></div>
    <header><div><p class="eyebrow">HARDWARE MONITORING</p><h1>{{tab==='overview'?t("Deine Geräte im Blick."):tab==='audit'?t("Änderungsprotokoll"):tab==='backup'?t("Sicherung & Wiederherstellung"):tab==='mail'?t("Benachrichtigungen"):t("Ereignisse & Entwarnungen")}}</h1><p>{{tab==='backup'?t("Geräte, Einstellungen und Historie sicher aufbewahren."):t("Serverzustände, Komponenten und Hardwaremeldungen an einem Ort.")}}</p></div><button class="refresh" :disabled="loading" @click="refresh">↻ &nbsp; {{loading?t("Wird geladen …"):t("Aktualisieren")}}</button></header>
    <div v-if="tab==='overview'" class="notice notification-summary" role="status"><span>{{t("E-Mail:")}} <strong>{{dashboard.notifications?.mail_enabled?t('aktiv'):t('inaktiv')}}</strong></span><span>{{t("DSM-Desktop:")}} <strong>{{dashboard.notifications?.desktop_enabled?t('aktiv'):t('inaktiv')}}</strong></span></div>
    <div v-else-if="tab==='mail'" class="notice" role="status"><strong>{{t("E-Mail:")}} {{dashboard.notifications?.mail_enabled?t('aktiv'):t('inaktiv')}} {{t("· DSM-Desktop:")}} {{dashboard.notifications?.desktop_enabled?t('aktiv'):t('inaktiv')}}</strong><p>{{t("Automatische Meldungen benötigen zusätzlich die Benachrichtigungsoption am Gerät und eine passende Ereignisauswahl.")}}</p><template v-if="admin && dashboard.notifications?.desktop_self_test_available"><label class="desktop-test-level">{{t("Schweregrad des Desktoptests")}}<select v-model="desktopTest.level" :disabled="desktopTest.busy"><option value="info">Info</option><option value="warn">{{t("Warnung")}}</option><option value="error">{{t("Fehler")}}</option></select></label><button class="refresh desktop-test" :disabled="desktopTest.busy" @click="sendDesktopTest">{{desktopTest.busy?t("Desktop-Test läuft …"):t("DSM-Desktop-Test an mich senden")}}</button><p>{{t("Manueller Test ausschließlich an deinen angemeldeten DSM-Benutzer. Dieser Test betrifft nur DSM-Desktopmeldungen. Zwischen Tests mindestens 30 Sekunden warten; er prüft auch drei Platzhalterwerte.")}}</p></template><p v-if="desktopTest.message" role="status">{{desktopTest.message}}</p><p v-if="desktopTest.error" role="alert">{{desktopTest.error}}</p></div>
    <div v-if="error" class="error" role="alert"><strong>{{t("Verbindung nicht verfügbar")}}</strong><p>{{error}}</p><small>{{t("Eine aktive DSM-Anmeldung und die Anwendungsberechtigung sind erforderlich. Vorhandene Daten können veraltet sein.")}}</small></div>
    <div v-if="tab==='overview'" class="summary"><div v-for="kind in ['ok','warning','critical','acknowledged','unknown']" :key="kind"><span :class="['status-icon',kind]">{{kind==='ok'||kind==='acknowledged'?'✓':kind==='unknown'?'?':'!'}}</span><div><strong>{{counts[kind]}}</strong><span>{{labels[kind]}}</span></div></div></div>
    <section v-if="tab==='overview'" class="content-grid"><div class="panel"><div class="panel-title"><h2>{{t("Geräte")}}</h2><button v-if="admin" class="primary" @click="editor={entry:null}">{{t("+ Gerät hinzufügen")}}</button><span v-else>{{devices.length}} {{t("registriert")}}</span></div><p v-if="!devices.length" class="empty">{{t("Noch keine Geräte eingerichtet.")}}<br><small>{{admin?t("Füge dein erstes Gerät mit HTTPS-Adresse und Gerätezugang hinzu."):t("Ein DSM-Administrator kann Geräte hinzufügen.")}}</small></p><button v-for="item in devices" :key="item.device.id" :class="['device-row',{selected:item.device.id===selected}]" @click="selected=item.device.id"><span class="server-icon">▤</span><div class="device-name"><strong>{{item.device.name}}</strong><small>{{item.device.endpoint}}</small><small v-if="item.acknowledged_count">{{t("{0} bestätigte Fehler",item.acknowledged_count)}}</small><small v-if="item.device.enabled===false">{{t("Überwachung pausiert")}}</small></div><span :class="['badge',overall(item)]">{{labels[overall(item)]}}</span></button></div>
      <div class="panel detail"><template v-if="focus"><div class="panel-title"><h2>{{focus.device.name}}</h2><button v-if="admin" class="refresh" @click="editor={entry:focus}">{{t("Bearbeiten")}}</button><span :class="['badge',overall(focus)]">{{labels[overall(focus)]}}</span></div><div class="meta"><span>{{t("Letzte gespeicherte Abfrage")}}<strong>{{timestamp(focus.last_poll)}}</strong></span><span>{{t("Pause zwischen Abfragen")}}<strong>{{focus.device.interval_seconds}} {{t("Sekunden")}}</strong></span><span v-if="focus.poll_timeout_seconds">{{t("Zeitlimit je Abfrage")}}<strong>{{focus.poll_timeout_seconds}} {{t("Sekunden")}}</strong></span></div><h3>{{t("Komponenten & Messwerte")}}</h3><p v-if="!focusSnapshot" class="empty">{{t("Noch keine erfolgreichen Messdaten vorhanden.")}}</p><table v-else><thead><tr><th>{{t("Komponente")}}</th><th>{{t("Messwert")}}</th><th>{{t("Zustand")}}</th></tr></thead><tbody><tr v-for="o in focusSnapshot.observations.filter(o=>!o.key.startsWith('coverage:'))" :key="o.key"><td :title="o.key">{{o.label}}</td><td>{{o.reading===null?'—':`${o.reading} ${o.unit??''}`}}</td><td><span :class="['badge',observationStatus(o,focusSnapshot,focus)]">{{observationLabel(o,focusSnapshot,focus)}}</span><small v-if="focus.alarm_statuses?.[o.key]?.status==='acknowledged' && !assessmentReason(o,focusSnapshot)" class="assessment-reason">{{t("Hardwarezustand:")}} {{labels[o.health]}}</small><small v-if="assessmentReason(o,focusSnapshot)" class="assessment-reason">{{assessmentReason(o,focusSnapshot)}}</small><small v-if="retainedObservationStatus(o,focusSnapshot,focus)" class="assessment-reason">{{t("Gespeicherter Alarm:")}} <span :class="['badge',retainedObservationStatus(o,focusSnapshot,focus)]">{{labels[retainedObservationStatus(o,focusSnapshot,focus)]}}</span></small></td></tr></tbody></table><h3>{{t("Aktuelle & gespeicherte Zustandsalarme")}}</h3><p class="muted">{{t("Sammelzustände werden bei passenden verknüpften Komponentenfehlern gebündelt. Gespeicherte Fehler bleiben bis zur Entwarnung oder zum manuellen Zurücksetzen erhalten.")}}</p><label class="alarm-filter">{{t("Alarmanzeige")}} <select v-model="alarmFilter"><option value="all">{{t("Alle Alarme")}}</option><option value="open">{{t("Offene Alarme")}}</option><option value="acknowledged">{{t("Bestätigte Alarme")}}</option></select></label><p v-if="!primaryAlarms(focus,alarmFilter).length && !summaryAlarms(focus,alarmFilter).length" class="muted">{{t("Keine gespeicherten offenen Alarme.")}}</p><AlarmRow v-for="a in primaryAlarms(focus,alarmFilter)" :key="a.key" :alarm="a" :device="focus" :dashboard="dashboard" @changed="refresh"/><details v-if="summaryAlarms(focus,alarmFilter).length" class="grouped-alarms"><summary>{{t("Zugeordnete Sammelzustände (")}}{{summaryAlarms(focus,alarmFilter).length}})</summary><AlarmRow v-for="a in summaryAlarms(focus,alarmFilter)" :key="a.key" :alarm="a" :device="focus" :dashboard="dashboard" @changed="refresh"/></details><details v-if="focusSnapshot"><summary>{{t("Erkannte Schnittstellen (")}}{{focusSnapshot.capabilities.length}})</summary><ul><li v-for="c in focusSnapshot.capabilities" :key="c.uri"><code>{{c.uri}}</code><span>{{capabilityText(c)}}</span></li></ul></details></template><p v-else class="empty">{{t("Wähle ein Gerät, um Details anzuzeigen.")}}</p></div></section>
    <section v-else-if="tab==='events'" class="panel events"><div class="panel-title"><h2>{{t("Letzte Meldungen")}}</h2><span>{{visibleEvents.length}} {{t("von")}} {{groupedEvents.length}} {{t("· letzte 100 Ereignisse")}}</span></div>
      <p class="form-note">{{dashboard.history?.settings.events_days?t("Ereignishistorie: {0} Tage Aufbewahrung.",dashboard.history.settings.events_days):t("Ereignishistorie: unbegrenzte Aufbewahrung.")}}</p><HistoryActions v-if="admin" :dashboard="dashboard" :filter="eventFilter" @changed="refresh"/><div class="event-filters"><label>{{t("Art")}}<select v-model="eventFilter.category"><option value="all">{{t("Alle Ereignisse")}}</option><option value="hardware">{{t("Hardwarezustände")}}</option><option value="log">{{t("Hardwarelogs")}}</option><option value="monitoring">{{t("Überwachungsabfragen")}}</option></select></label><label>{{t("Zustand")}}<select v-model="eventFilter.health"><option value="all">{{t("Alle Zustände")}}</option><option value="critical">{{t("Kritisch")}}</option><option value="warning">{{t("Warnung")}}</option><option value="ok">{{t("Entwarnung / OK")}}</option></select></label><label>{{t("Gerät")}}<select v-model="eventFilter.device"><option value="all">{{t("Alle Geräte")}}</option><option v-for="[id,name] in eventDevices" :key="id" :value="id">{{name}}</option></select></label></div>
      <p class="event-hint">{{t("Hardwarelogs enthalten Meldungen des Servers. Ein Logeintrag allein ist kein Nachweis eines aktuell bestehenden Fehlers. Entwarnungen für Redfish-Abfragen betreffen nur die Überwachung.")}}</p>
      <p v-if="!visibleEvents.length" class="empty">{{t("Keine passenden Ereignisse vorhanden.")}}</p><table v-else><thead><tr><th>{{t("Erfasst am")}}</th><th>{{t("Gerät")}}</th><th>{{t("Art")}}</th><th>{{t("Zustand")}}</th><th>{{t("Meldung")}}</th><th>{{t("Versandstatus")}}</th></tr></thead><tbody><tr v-for="e in visibleEvents" :key="e.id"><td>{{timestamp(e.created)}}<small v-if="sourceTimestamp(e.source_created)" class="log-time">{{t("Hardwarelog:")}} {{sourceTimestamp(e.source_created)}}</small></td><td :title="e.device">{{e.device_name??e.device}}</td><td>{{eventType(e)}}</td><td><span :class="['badge',e.health]">{{e.kind==='recovery'?t("Entwarnung"):labels[e.health]}}</span></td><td>{{e.message}}<small v-if="e.merged_count>1" class="log-time" :title="e.source_keys.join('\n')">{{e.merged_count}} {{t("bestätigte Darstellungen zusammengeführt")}}</small></td><td>{{deliveryText(e)}}<button v-if="admin" class="refresh replay-action" @click="replayEvent=e">{{t('E-Mail erneut senden …')}}</button></td></tr></tbody></table></section>
    <div v-else-if="tab==='backup' && admin"><HistorySettings :dashboard="dashboard" @changed="refresh"/><BackupSettings :dashboard="dashboard" @changed="refresh"/></div><div v-else-if="tab==='mail' && admin && dashboard.mail"><NotificationSettings :dashboard="dashboard" @saved="refresh"/><MailSettings :dashboard="dashboard" @saved="refresh"/></div><section v-else-if="admin" class="panel events"><div class="panel-title"><h2>{{t("Letzte Änderungen")}}</h2><span>{{t("Anzeige: bis zu 50 Einträge; Aufbewahrung: maximal 10'000 Einträge.")}}</span></div><p v-if="!dashboard.audit?.length" class="empty">{{t("Noch keine administrativen Änderungen.")}}</p><table v-else><thead><tr><th>{{t("Zeit")}}</th><th>{{t("Benutzer")}}</th><th>{{t("Aktion")}}</th><th>{{t("Gerät")}}</th><th>{{t("Ergebnis")}}</th></tr></thead><tbody><tr v-for="(entry,index) in dashboard.audit" :key="index"><td>{{timestamp(entry.created)}}</td><td>{{entry.actor}}</td><td>{{({'history.settings':t('Aufbewahrungsregeln geändert'),'history.cleanup':t('Historie bereinigt'),'history.cleanup.result':t('Ergebnis der Bereinigung'),'mail.replay':t('Ereignis-E-Mail manuell vorgemerkt'),'mail.replay.result':t('Ergebnis des manuellen E-Mail-Versands'),'alarm.reset':t("Gespeicherten Alarm zurückgesetzt"),'alarm.acknowledge':t("Hardwarealarm bestätigt"),'alarm.reopen':t("Bestätigung aufgehoben"),'alarm.invalidate':t("Bestätigung automatisch beendet"),'events.export':t("Ereignisse als CSV exportiert"),'events.clear':t("Ereignislog geleert"),'backup.export':t("Sicherung erstellt"),'backup.restore':t("Sicherung wiederhergestellt"),'device.create':t("Gerät angelegt"),'device.update':t("Gerät geändert"),'device.delete':t("Gerät entfernt"),'device.test':t("Verbindung geprüft"),'notification.desktop_test':t("Desktoptest an eigenen Benutzer"),'mail.settings':t("E-Mail-Einstellungen geändert"),'notification.settings':t("Kanäle und Ereignisauswahl geändert"),'mail.test':t("Testmail an erste Empfängeradresse")})[entry.action]??entry.action}}</td><td>{{devices.find(d=>d.device.id===entry.device)?.device.name??(entry.device==='unsaved'?t("Noch nicht gespeichert"):entry.device==='self'?t("Eigener DSM-Benutzer"):entry.device==='application'?t("Anwendung"):entry.device==='events'?t("Ereignislog"):entry.device)}}</td><td>{{({'ok':t("Erfolgreich"),'submitted':t("An DSM übergeben"),'started':t("Gestartet"),'desktop_test_rejected':t("Von DSM abgewiesen"),'desktop_test_unavailable':t("Desktop-Aufruf nicht verfügbar")})[entry.outcome]??entry.outcome}}</td></tr></tbody></table></section>
    <footer><span>{{t("Ergänzende Hardwareüberwachung für deine Infrastruktur")}}<br>{{t("Oberfläche")}} {{uiBuild}}</span><span>{{dashboard?.user?.name??t("DSM-Anmeldung")}} · {{dashboard?.user?.role==='administrator'?t("Administration"):t("Lesezugriff")}}<br><small v-if="dashboard">{{t("Stand:")}} {{timestamp(dashboard.generated)}}</small></span></footer>
  </main>
  <MailReplay v-if="replayEvent && admin" :event="replayEvent" :dashboard="dashboard" @close="replayEvent=null" @changed="refresh"/>
  <DeviceEditor v-if="editor && admin" :entry="editor.entry" :dashboard="dashboard" @close="editor=null" @saved="saved"/>
</div>
</template>
